import polars as pl


def transform(raw: pl.DataFrame) -> pl.DataFrame:
    def parse_amount(s: pl.Expr) -> pl.Expr:
        cleaned = (
            s.str.strip_chars()
            .str.replace_all(",", "")
            .str.replace(r"^\((.*)\)$", "-$1", strict=False)
        )
        return cleaned.cast(pl.Float64, strict=False).round(2)

    def parse_balance(s: pl.Expr) -> pl.Expr:
        cleaned = s.str.strip_chars().str.replace_all(",", "")
        return cleaned.cast(pl.Float64, strict=False).round(2)

    return raw.select(
        account=pl.col("Account").str.strip_chars(),
        txn_date=pl.col("Date").str.to_date("%m/%d/%Y", strict=False),
        description=pl.col("Memo").str.strip_chars(),
        amount=parse_amount(pl.col("Amount")),
        balance=parse_balance(pl.col("Balance")),
        reference=pl.col("Reference").str.strip_chars(),
    )
